786	func prepareTrailCreateBranch(w, errW io.Writer, repo *git.Repository, branch, currentBranch string, noBranch bool) (trailCreateBranchState, error) {
787		var state trailCreateBranchState
788		if noBranch || branch == "" {
789			// Branchless trails have no remote branch to create, fetch, or push.
790			return state, nil
791		}
792	
793		state.NeedsCreation = branchNeedsCreation(repo, branch)
794		existedOnOrigin, existErr := branchExistsOnOrigin(branch)
795		if existErr != nil {
796			fmt.Fprintf(errW, "Warning: could not check whether branch %s already exists on origin: %v\n", branch, existErr)
797			existedOnOrigin = true
798		}
799	
800		if err := ensureTrailCreateBranchExists(w, repo, branch, currentBranch, existedOnOrigin, &state); err != nil {
801			return state, err
802		}
803	
804		// For branch-backed trails, always push the branch first: the trail binds to a
805		// remote branch, so deliver it before creating the trail rather than letting
806		// the server backfill it at the base tip. Branchless trails skip this entirely.
807		if err := pushBranchToOrigin(branch); err != nil {
808			cleanupCreatedTrailBranch(repo, branch, state.LocalCreated, false, errW)
809			return state, fmt.Errorf("failed to push branch %q to origin: %w\nhint: the trail was not created because its branch could not be delivered to the remote.\n  - if this is an auth error, link your GitHub account and retry\n  - if this is a non-fast-forward, update branch %q from origin and retry", branch, err, branch)
810		}
811		state.RemotePushed = !existedOnOrigin
812		fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
813		return state, nil
814	}
